package com.kitecast.data

import kotlinx.coroutines.delay
import java.io.IOException

suspend fun <T> retryWithBackoff(attempts: Int = 3, baseMs: Long = 500, block: suspend () -> T): T {
    var wait = baseMs
    repeat(attempts - 1) {
        try { return block() } catch (e: IOException) { delay(wait); wait *= 2 }
    }
    return block()
}

class WeatherRepositoryRetryTest {
    @Test fun `succeeds on third attempt`() = runTest {
        val api = FlakyApi(failures = 2)
        val repo = WeatherRepository(api, StandardTestDispatcher(testScheduler))
        repo.fetchForecast("tarifa")
        assertEquals(3, api.calls)
    }
    @Test fun `waits 500 then 1000 ms`() = runTest {
        val api = FlakyApi(failures = 2)
        val repo = WeatherRepository(api)
        repo.fetchForecast("tarifa")
        assertEquals(1500, currentTime)
    }
    @Test fun `does not retry on HttpException`() = runTest {
        val api = FlakyApi(failures = 1, error = HttpException(500))
        val repo = WeatherRepository(api, StandardTestDispatcher(testScheduler))
        assertFailsWith<HttpException> { repo.fetchForecast("tarifa") }
        assertEquals(1, api.calls)
    }
}
